() => {
  const rows = document.querySelectorAll('table tr');
  for (const row of rows) {
    const text = row.innerText;
    if (text.startsWith('COMNL')) {
      // Extract all cells
      const cells = Array.from(row.querySelectorAll('td, th')).map(td => td.innerText.trim());
      return { cells, html: row.outerHTML.slice(0, 2000) };
    }
  }
  return 'COMNL row not found';
}

() => {
  const rows = document.querySelectorAll('table tr');
  for (const row of rows) {
    const first = row.querySelector('td');
    if (first && first.innerText.trim() === 'COMNL') {
      const cells = Array.from(row.querySelectorAll('td')).map(td => td.innerText.trim());
      return cells;
    }
  }
  return 'COMNL row not found';
}
